def memoized_property(func):
    name = '_cache_' + func.__name__
    @property
    def wrapper(self):
        if not hasattr(self, name):
            setattr(self, name, func(self))
        return getattr(self, name)
    return wrapper

class Expensive:
    @memoized_property
    def data(self):
        print('Computing')
        return [1, 2, 3]

